/**
 * Admin Routes — Dashboard, order management, customers, audit log.
 * All routes require admin authentication.
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const adminController = require('../controllers/admin.controller');
const { authenticate, authorize } = require('../middleware/auth.middleware');
const { adminLimiter } = require('../middleware/rate-limiter.middleware');
const { validate, schemas } = require('../middleware/validator.middleware');
const { auditLog } = require('../middleware/audit-log.middleware');

// All admin routes require auth + admin role
router.use(authenticate);
router.use(authorize('admin', 'superadmin'));
router.use(adminLimiter);

// Dashboard stats
router.get('/dashboard', adminController.getDashboard);

// Admin's own account/profile
router.get('/account', adminController.getAccount);

// Orders management
router.get('/orders', adminController.getAllOrders);
router.put('/orders/:id/status',
  validate(schemas.updateShippingStatus),
  auditLog('UPDATE_ORDER_STATUS', (req) => ({
    targetModel: 'Order', targetId: req.params.id, changes: req.body,
  })),
  adminController.updateOrderStatus
);

// Cancellations
router.get('/cancellations', adminController.getCancellations);

// Customers
router.get('/customers', adminController.getCustomers);

// Audit log
router.get('/audit-log', adminController.getAuditLog);

module.exports = router;
